217	    /**
218	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
219	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
220	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
221	     * blank (e.g. {@code "   "}). The offending field names are reported through an
222	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
223	     * as a 400 response carrying an {@code errors} array of field names.
224	     *
225	     * @param ownerFieldsDto the submitted owner fields
226	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
227	     */
228	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
229	        List<String> blankFields = new ArrayList<>();
230	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
231	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
232	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
233	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
234	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
235	        if (!blankFields.isEmpty()) {
236	            throw new InvalidOwnerFieldsException(blankFields);
237	        }
238	    }
239	
240	    private void addIfBlank(List<String> blankFields, String field, String value) {
241	        if (value != null && value.isBlank()) {
242	            blankFields.add(field);
243	        }
244	    }
245	
246	    /**
247	     * Normalizes a telephone number submitted to the create endpoint by removing every non-digit
248	     * character. The result must contain exactly 10 digits; otherwise the submission is rejected as
249	     * a 400 (via {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice}
250	     * renders with {@code telephone} in its {@code errors} array).
251	     *
252	     * @param telephone the raw telephone value from the request
253	     * @return the stripped, 10-digit telephone to store and return
254	     * @throws InvalidOwnerFieldsException if the stripped value is not exactly 10 digits
255	     */
256	    private String normalizeTelephone(String telephone) {
257	        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
258	        if (digits.length() != 10) {
259	            throw new InvalidOwnerFieldsException(List.of("telephone"));
260	        }
261	        return digits;
262	    }
263	
264	    /**
265	     * Normalizes an owner's optional email address. When present it is stored and returned
266	     * lower-cased (using {@link Locale#ROOT} so normalization is locale-independent). A missing
267	     * (null) email is left as-is. Syntactic validity is enforced by Bean Validation ({@code @Email}
268	     * on {@link OwnerFieldsDto}), so an invalid address is already rejected as a 400 before this
269	     * method runs.
270	     *
271	     * @param email the raw email value from the request, or {@code null} when omitted
272	     * @return the lower-cased email, or {@code null} when none was supplied
273	     */
274	    private String normalizeEmail(String email) {
275	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
276	    }
277	
278	    /**
279	     * Rejects a create request whose normalized telephone is already used by any existing owner.
280	     * Existing owners' telephones are normalized the same way (non-digit characters stripped) before
281	     * comparison, so numbers that differ only in formatting still collide. A collision is reported
282	     * through a {@link DuplicateOwnerTelephoneException}, which the {@code ExceptionControllerAdvice}
283	     * renders as a 409 Conflict response.
284	     *
285	     * @param normalizedTelephone the stripped, 10-digit telephone of the owner being created
286	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
287	     */
288	    private void rejectDuplicateTelephone(String normalizedTelephone) {
289	        boolean duplicate = this.clinicService.findAllOwners().stream()
290	            .map(Owner::getTelephone)
291	            .filter(existing -> existing != null)
292	            .map(existing -> existing.replaceAll("\\D", ""))
293	            .anyMatch(normalizedTelephone::equals);
294	        if (duplicate) {
295	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
296	        }
297	    }
